function sh(n){var j={};try{j=$(n).first().json||{};}catch(e){return [];}return j.values||[];}
function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');}

var ir=sh('Read INVESTORS');var ih=(ir[0]||[]).map(function(x){return String(x||'').trim();});var ilc=ih.map(function(x){return x.toLowerCase();});
function ic(n){return ilc.indexOf(n);}
var iN=ic('investor_name');if(iN<0)iN=ic('firm');if(iN<0)iN=0;
var iE=ic('email');var iD=ic('do_not_contact');var iS=ic('sectors');if(iS<0)iS=ic('sector');var iSt=ic('stage');var iC=ic('cheque_cr');if(iC<0)iC=ic('cheque');
var inv=[];
for(var a=1;a<ir.length;a++){var r=ir[a]||[];var nm=String(r[iN]||'').trim();if(!nm)continue;inv.push({row:a+1,name:nm,norm:norm(nm),email:iE>=0?String(r[iE]||'').trim():'',dnc:iD>=0?String(r[iD]||'').trim():'',sector:iS>=0?String(r[iS]||'').slice(0,90):'',stage:iSt>=0?String(r[iSt]||'').slice(0,60):'',cheque:iC>=0?String(r[iC]||'').slice(0,40):''});}
var targets=['ironpillar','in44capital','liftt','lumikai','navamcapital','forefrontventurepartners'];
var hits={};for(var t=0;t<targets.length;t++){hits[targets[t]]=[];for(var b=0;b<inv.length;b++){var nn=inv[b].norm;if(nn.indexOf(targets[t])>-1||targets[t].indexOf(nn)>-1&&nn.length>3)hits[targets[t]].push(inv[b]);}}

var sr=sh('Read STARTUPS');var shh=(sr[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
var cS=shh.indexOf('startup'),cSec=shh.indexOf('sector'),cStg=shh.indexOf('stage'),cR=shh.indexOf('raise_inr_cr'),cRev=shh.indexOf('revenue'),cA=shh.indexOf('active'),cRec=shh.indexOf('recommended_raise_cr');
var su=[];
for(var e=1;e<sr.length;e++){var q=sr[e]||[];var nm2=String(q[cS]||'').trim();if(!nm2)continue;
 var raw=String(q[cR]||'').trim();var num=parseFloat(raw.replace(/[^0-9.]/g,''));if(isNaN(num))num=null;
 su.push({startup:nm2,sector:String(q[cSec]||'').trim(),stage:String(q[cStg]||'').trim(),raise_raw:raw,raise_cr:num,revenue:String(q[cRev]||'').trim().slice(0,40),active:String(q[cA]||'').trim(),rec:cRec>=0?String(q[cRec]||'').trim():''});}
var act=su.filter(function(x){return !/^(no|false|0)$/i.test(x.active);});
function cnt(arr,f){var n=0;for(var i=0;i<arr.length;i++)if(f(arr[i]))n++;return n;}
var bands={total:su.length,active:act.length,
 active_ge_100cr:cnt(act,function(x){return x.raise_cr!==null&&x.raise_cr>=100;}),
 active_ge_50cr:cnt(act,function(x){return x.raise_cr!==null&&x.raise_cr>=50;}),
 active_ge_1p5cr:cnt(act,function(x){return x.raise_cr!==null&&x.raise_cr>=1.5;}),
 active_ge_0p5cr:cnt(act,function(x){return x.raise_cr!==null&&x.raise_cr>=0.5;}),
 active_0p5_to_1p5:cnt(act,function(x){return x.raise_cr!==null&&x.raise_cr>=0.5&&x.raise_cr<=1.5;}),
 active_blank_raise:cnt(act,function(x){return x.raise_cr===null;}),
 active_max_raise:act.reduce(function(m,x){return (x.raise_cr!==null&&x.raise_cr>m)?x.raise_cr:m;},0)};
var sectors={};for(var s2=0;s2<act.length;s2++){var k=act[s2].sector||'(blank)';sectors[k]=(sectors[k]||0)+1;}
var stages={};for(var s3=0;s3<act.length;s3++){var k2=act[s3].stage||'(blank)';stages[k2]=(stages[k2]||0)+1;}

var orr=sh('Read ONBOARDING');var oh=(orr[0]||[]).map(function(x){return String(x||'').trim().toLowerCase();});
var oF=oh.indexOf('firm'),oE=oh.indexOf('email'),oC=oh.indexOf('contact'),oS=oh.indexOf('status'),oOc=oh.indexOf('outcome'),oRN=oh.indexOf('review_note'),oSj=oh.indexOf('subject'),oTh=oh.indexOf('thread_id'),oSd=oh.indexOf('sent_date');
var look=['lumikai','ironpillar','in44','liftt','lightrock'];var found=[];
for(var f2=1;f2<orr.length;f2++){var w=orr[f2]||[];var blob=norm(String(w[oF]||'')+' '+String(w[oE]||'')+' '+String(w[oSj]||''));
 for(var g=0;g<look.length;g++){if(blob.indexOf(look[g])>-1){found.push({row:f2+1,key:look[g],firm:String(w[oF]||''),contact:String(w[oC]||''),email:String(w[oE]||''),status:String(w[oS]||''),outcome:String(w[oOc]||''),sent_date:String(w[oSd]||''),thread_id:String(w[oTh]||''),review_note:String(w[oRN]||'').slice(0,200),subject:String(w[oSj]||'').slice(0,120)});break;}}}

return [{json:{investorsHeader:ih,investorsCount:inv.length,dupHits:hits,startupsHeader:shh,bands:bands,sectors:sectors,stages:stages,startupsAll:act.map(function(x){return x.startup+' | '+x.sector+' | '+x.stage+' | '+x.raise_raw;}),onboardingLookups:found}}];
